using System;using System.IO;using System.Drawing;using System.Windows.Forms;using System.Reflection;using System.Diagnostics;using System.Threading;using System.Threading.Tasks;
namespace ExtremeLand {
 public sealed class LauncherForm:Form {
  readonly Engine engine;Config config;readonly Label status,detail,version;readonly Button play,update,account,settings,publish,import,folder,cancel;readonly ProgressBar progress;bool busy;CancellationTokenSource cancellation;
  public LauncherForm(Engine e){engine=e;string cfg=e.Safe("settings.json");config=File.Exists(cfg)?Json.Read<Config>(cfg):Publisher.Embedded(Assembly.GetExecutingAssembly().Location);Text="ExtremeLand Launcher";ClientSize=new Size(1080,680);MinimumSize=MaximumSize=Size;FormBorderStyle=FormBorderStyle.FixedSingle;MaximizeBox=false;StartPosition=FormStartPosition.CenterScreen;BackColor=Color.FromArgb(11,17,24);ForeColor=Color.FromArgb(237,232,218);Font=new Font("Segoe UI",10);AutoScaleMode=AutoScaleMode.None;
   var hero=new PictureBox{Bounds=new Rectangle(24,70,500,500),SizeMode=PictureBoxSizeMode.Zoom};using(var stream=Assembly.GetExecutingAssembly().GetManifestResourceStream("logo.png"))using(var decoded=new Bitmap(stream)){hero.Image=new Bitmap(decoded);}Controls.Add(hero);
   AddLabel("EXTREMELAND",570,65,470,48,28,Color.FromArgb(232,190,103));AddLabel("TEMPORADA 1 · LA RUEDA ROTA",574,119,450,26,11,Color.FromArgb(95,207,205));AddLabel("TU PRÓXIMA AVENTURA",574,180,430,32,18,ForeColor);
   AddLabel("Abre, actualiza y juega.\nLos mods se preparan automáticamente antes de entrar.",574,224,445,57,11,Color.FromArgb(163,178,188));version=AddLabel("Minecraft Java 1.20.1 · Forge",574,301,445,26,10,ForeColor);status=AddLabel("",574,337,445,29,11,Color.FromArgb(95,207,205));detail=AddLabel("",574,371,445,51,10,Color.FromArgb(163,178,188));detail.AutoEllipsis=true;
   progress=new ProgressBar{Bounds=new Rectangle(574,436,440,8),Style=ProgressBarStyle.Continuous};Controls.Add(progress);
   play=Button("JUGAR",574,468,286,52,Color.FromArgb(206,163,74),Color.FromArgb(15,21,28));play.Font=new Font("Segoe UI",14,FontStyle.Bold);play.Click+=async delegate{await Sync(true);};
   update=Button("ACTUALIZAR",872,468,142,52,Color.FromArgb(29,57,64),ForeColor);update.Click+=async delegate{await Sync(false);};
   account=Button("Cuenta Microsoft",574,534,210,33,Color.FromArgb(22,32,43),ForeColor);account.Click+=async delegate{await Login();};settings=Button("Configuración",804,534,210,33,Color.FromArgb(22,32,43),ForeColor);settings.Click+=delegate{Configure();};
   import=Button("Importar mi mundo",574,580,210,30,BackColor,Color.FromArgb(156,178,188));import.Click+=async delegate{await Import();};folder=Button("Carpeta de juego",804,580,210,30,BackColor,Color.FromArgb(156,178,188));folder.Click+=delegate{Directory.CreateDirectory(e.Game);Process.Start("explorer.exe",Engine.Quote(e.Game));};
   publish=Button("Herramientas del creador",24,615,260,30,BackColor,Color.FromArgb(156,178,188));publish.Click+=async delegate{await Publish();};cancel=Button("Cancelar",906,633,108,28,BackColor,ForeColor);cancel.Click+=delegate{if(cancellation!=null)cancellation.Cancel();};cancel.Visible=false;
   AddLabel("Actualización antes de jugar · Acceso de Minecraft mediante Prism Launcher",24,25,980,23,9,Color.FromArgb(126,151,166));AddLabel("Conecta con tus amigos mediante las invitaciones de Essential.",24,577,515,28,9,Color.FromArgb(126,151,166));
   engine.Progress=delegate(string text,long done,long total){if(!IsDisposed&&IsHandleCreated)BeginInvoke((Action)delegate{status.Text=text;progress.Style=total>0?ProgressBarStyle.Continuous:ProgressBarStyle.Marquee;if(total>0){progress.Value=(int)Math.Min(100,done*100/total);detail.Text=String.Format("{0:0.0} / {1:0.0} MB",done/1048576d,total/1048576d);}});};FormClosing+=delegate(object sender,FormClosingEventArgs args){if(busy){cancellation.Cancel();args.Cancel=true;status.Text="Terminando la operación de forma segura...";}};RefreshState();
  }
  Label AddLabel(string s,int x,int y,int w,int h,int size,Color color){var l=new Label{Text=s,Bounds=new Rectangle(x,y,w,h),Font=new Font("Segoe UI",size,size>=18?FontStyle.Bold:FontStyle.Regular),ForeColor=color,BackColor=Color.Transparent};Controls.Add(l);return l;}
  Button Button(string s,int x,int y,int w,int h,Color bg,Color fg){var b=new Button{Text=s,Bounds=new Rectangle(x,y,w,h),BackColor=bg,ForeColor=fg,FlatStyle=FlatStyle.Flat,Cursor=Cursors.Hand};b.FlatAppearance.BorderSize=0;Controls.Add(b);return b;}
  void RefreshState(){bool installed=File.Exists(engine.Safe("installed.json"));if(installed){try{version.Text="Paquete instalado · "+Json.Read<Pack>(engine.Safe("installed.json")).version;}catch{version.Text="Paquete pendiente de reparación";}}status.Text=String.IsNullOrWhiteSpace(config.channel)?"PUBLICACIÓN PENDIENTE":installed?"LISTO PARA BUSCAR ACTUALIZACIONES":"LISTO PARA INSTALAR";detail.Text=String.IsNullOrWhiteSpace(config.channel)?"El launcher está preparado. Falta conectar la publicación de GitHub para descargar el paquete.":"Al pulsar Jugar se comprueba la versión y se descargan los archivos que hayan cambiado.";play.Text=String.IsNullOrWhiteSpace(config.channel)?"CONECTAR PUBLICACIÓN":"JUGAR";}
  void Busy(bool value){busy=value;foreach(var b in new[]{play,update,account,settings,publish,import,folder})b.Enabled=!value;cancel.Visible=value;progress.Style=value?ProgressBarStyle.Marquee:ProgressBarStyle.Continuous;if(!value)progress.Value=0;}
  async Task Work(Func<Task> action){if(busy)return;Busy(true);cancellation=new CancellationTokenSource();try{await action();}catch(OperationCanceledException){status.Text="Descarga pausada";detail.Text="Puedes volver a intentar. Las descargas compatibles se reanudan.";}catch(Exception ex){status.Text="No se pudo completar";detail.Text=ex.Message;MessageBox.Show(this,ex.Message,"ExtremeLand",MessageBoxButtons.OK,MessageBoxIcon.Information);}finally{Busy(false);}}
  async Task Sync(bool launch){if(String.IsNullOrWhiteSpace(config.channel)){Configure();return;}await Work(async delegate{Pack p=null;await Task.Run(async delegate{p=await engine.Fetch(config.channel,cancellation.Token);await engine.Apply(p,config.ram,cancellation.Token);await engine.EnsureBackend(cancellation.Token);});version.Text="Paquete instalado · "+p.version;status.Text="ACTUALIZACIÓN COMPLETA";detail.Text="La primera vez, conecta tu cuenta comprada de Minecraft en la ventana de acceso.";if(launch)engine.Start(false);});}
  async Task Login(){await Work(async delegate{await Task.Run(async delegate{await engine.EnsureBackend(cancellation.Token);});engine.Start(true);status.Text="VENTANA DE ACCESO ABIERTA";detail.Text="En Prism abre Configuración → Cuentas → Añadir Microsoft. Cierra esa ventana antes de actualizar.";});}
  void Configure(){using(var d=new SettingsDialog(config)){if(d.ShowDialog(this)==DialogResult.OK){config=d.Value;Json.Write(engine.Safe("settings.json"),config);RefreshState();}}}
  async Task Import(){using(var d=new FolderBrowserDialog{Description="Selecciona el mundo que contiene level.dat. Se copiará; el original se conserva."}){if(d.ShowDialog(this)!=DialogResult.OK)return;await Work(async delegate{string target=await Task.Run(()=>engine.ImportWorld(d.SelectedPath));status.Text="MUNDO COPIADO";detail.Text="Tu mundo aparecerá en Un jugador. El original se conserva.";});}}
  async Task Publish(){if(String.IsNullOrWhiteSpace(config.channel)){Configure();if(String.IsNullOrWhiteSpace(config.channel))return;}string repo;try{var u=new Uri(config.channel);var parts=u.AbsolutePath.Trim('/').Split('/');if(u.Host!="github.com"||parts.Length<2)throw new Exception();repo=parts[0]+"/"+parts[1];}catch{MessageBox.Show("Configura primero usuario/repositorio de GitHub.");return;}
   using(var source=new FolderBrowserDialog{Description="Selecciona tu perfil actualizado de ExtremeLand (la carpeta que contiene mods)."}){if(source.ShowDialog(this)!=DialogResult.OK)return;using(var destination=new FolderBrowserDialog{Description="Elige dónde preparar los archivos para publicar."}){if(destination.ShowDialog(this)!=DialogResult.OK)return;string ver=Prompt("Versión del paquete","2.0.3");if(ver==null)return;await Work(async delegate{string output=Path.Combine(destination.SelectedPath,"Publicar-ExtremeLand-"+ver+"-"+DateTime.Now.ToString("yyyyMMdd-HHmmss"));await Task.Run(()=>{var pack=Publisher.Prepare(source.SelectedPath,output,repo,ver);engine.Validate(pack);Publisher.Export(Assembly.GetExecutingAssembly().Location,Path.Combine(output,"ExtremeLandLauncher.exe"),config);File.WriteAllText(Path.Combine(output,"PUBLICAR.txt"),"Crea una publicación en GitHub con etiqueta pack-"+ver+". Adjunta channel.json, los JAR y ExtremeLandLauncher.exe de esta carpeta. Publica la versión. Tus amigos solo necesitan el EXE; este descargará los mods. No se copiaron mundos ni cuentas.");});status.Text="PUBLICACIÓN PREPARADA";detail.Text="Sube channel.json, los JAR y el launcher a GitHub Releases con la etiqueta indicada en PUBLICAR.txt.";Process.Start("explorer.exe",Engine.Quote(output));});}}}
  static string Prompt(string title,string value){using(var d=new Form{Text=title,ClientSize=new Size(390,125),StartPosition=FormStartPosition.CenterParent,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false,MinimizeBox=false}){var text=new TextBox{Text=value,Bounds=new Rectangle(20,20,350,25)};var ok=new Button{Text="Aceptar",DialogResult=DialogResult.OK,Bounds=new Rectangle(260,68,110,32)};d.Controls.Add(text);d.Controls.Add(ok);d.AcceptButton=ok;return d.ShowDialog()==DialogResult.OK?text.Text:null;}}
 }
}
